contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public payable {
        uint64 beforeNumber = c.number(); if (__ESBMC_reverted()) return;
        uint64 beforeTimestamp = c.timestamp(); if (__ESBMC_reverted()) return;
        uint256 beforeBasefee = c.basefee(); if (__ESBMC_reverted()) return;
        bytes32 beforeHash = c.hash(); if (__ESBMC_reverted()) return;
        uint64 beforeSequenceNumber = c.sequenceNumber(); if (__ESBMC_reverted()) return;
        bytes32 beforeBatcherHash = c.batcherHash(); if (__ESBMC_reverted()) return;
        uint256 beforeL1FeeOverhead = c.l1FeeOverhead(); if (__ESBMC_reverted()) return;
        uint256 beforeL1FeeScalar = c.l1FeeScalar(); if (__ESBMC_reverted()) return;

        bool reverted;

        c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        bool unchanged = beforeNumber == c.number()
            && beforeTimestamp == c.timestamp()
            && beforeBasefee == c.basefee()
            && beforeHash == c.hash()
            && beforeSequenceNumber == c.sequenceNumber()
            && beforeBatcherHash == c.batcherHash()
            && beforeL1FeeOverhead == c.l1FeeOverhead()
            && beforeL1FeeScalar == c.l1FeeScalar();

        assert(reverted && unchanged);
    }

    receive() external payable {}
}

