import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    L1Block c;

    function setUp() public {
        c = new L1Block();
    }

    function _run(uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) internal {
        uint64 beforeNumber;
        try c.number() returns (uint64 __r) { beforeNumber = __r; } catch { return; }
        uint64 beforeTimestamp;
        try c.timestamp() returns (uint64 __r) { beforeTimestamp = __r; } catch { return; }
        uint256 beforeBasefee;
        try c.basefee() returns (uint256 __r) { beforeBasefee = __r; } catch { return; }
        bytes32 beforeHash;
        try c.hash() returns (bytes32 __r) { beforeHash = __r; } catch { return; }
        uint64 beforeSequenceNumber;
        try c.sequenceNumber() returns (uint64 __r) { beforeSequenceNumber = __r; } catch { return; }
        bytes32 beforeBatcherHash;
        try c.batcherHash() returns (bytes32 __r) { beforeBatcherHash = __r; } catch { return; }
        uint256 beforeL1FeeOverhead;
        try c.l1FeeOverhead() returns (uint256 __r) { beforeL1FeeOverhead = __r; } catch { return; }
        uint256 beforeL1FeeScalar;
        try c.l1FeeScalar() returns (uint256 __r) { beforeL1FeeScalar = __r; } catch { return; }
        bool reverted;
        try c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }
        bool unchanged = beforeNumber == c.number()
            && beforeTimestamp == c.timestamp()
            && beforeBasefee == c.basefee()
            && beforeHash == c.hash()
